package handler

import (
	"errors"
	"log/slog"
	"reflect"
	"sync"

	"github.com/liweiyi88/onedump/config"
	"github.com/liweiyi88/onedump/jobresult"
	"github.com/liweiyi88/onedump/notifier/console"
)

type Notifier interface {
	Notify(results []*jobresult.JobResult) error
}

type DumpHandler struct {
	Dump *config.Dump
	mu   sync.Mutex
}

func NewDumpHandler(dump *config.Dump) *DumpHandler {
	return &DumpHandler{
		Dump: dump,
	}
}

func (d *DumpHandler) Do() error {
	var dumpErr error
	var wg sync.WaitGroup

	results := make([]*jobresult.JobResult, 0, len(d.Dump.Jobs))
	limiter := make(chan struct{}, d.Dump.MaxJobs)

	for _, job := range d.Dump.Jobs {
		wg.Add(1)
		limiter <- struct{}{}

		go func(job *config.Job) {
			defer func() {
				<-limiter
				wg.Done()
			}()

			slog.Debug("start to process job", slog.String("job", job.Name))

			jobHandler := NewJobHandler(job)
			result := jobHandler.Do()

			d.mu.Lock()
			if result.Error != nil {
				dumpErr = errors.Join(dumpErr, result.Error)
			}

			results = append(results, result)
			d.mu.Unlock()

		}(job)
	}

	wg.Wait()

	err := d.notify(results)

	if err != nil {
		dumpErr = errors.Join(dumpErr, err)
	}

	return dumpErr
}

func (d *DumpHandler) notify(results []*jobresult.JobResult) error {
	var errs error
	var wg sync.WaitGroup
	for _, notifier := range d.getNotifiers() {
		wg.Add(1)
		go func(notifier Notifier) {
			notifErr := notifier.Notify(results)
			if notifErr != nil {
				d.mu.Lock()
				errs = errors.Join(errs, notifErr)
				d.mu.Unlock()
			}
			wg.Done()
		}(notifier)
	}

	wg.Wait()
	return errs
}

func (d *DumpHandler) getNotifiers() []Notifier {
	var notifiers []Notifier
	notifiers = append(notifiers, console.New())

	v := reflect.ValueOf(d.Dump.Notifier)
	for i := 0; i < v.NumField(); i++ {
		field := v.Field(i)
		switch field.Kind() {
		case reflect.Slice:
			for i := 0; i < field.Len(); i++ {
				n, ok := field.Index(i).Interface().(Notifier)
				if ok {
					notifiers = append(notifiers, n)
				}
			}
		}
	}

	return notifiers
}
package handler

import (
	"compress/gzip"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"reflect"
	"sync"
	"time"

	"github.com/liweiyi88/onedump/config"
	"github.com/liweiyi88/onedump/dumper"
	"github.com/liweiyi88/onedump/fileutil"
	"github.com/liweiyi88/onedump/jobresult"
	"github.com/liweiyi88/onedump/storage"
)

type JobHandler struct {
	Job *config.Job
}

// Create a new job handler.
func NewJobHandler(job *config.Job) *JobHandler {
	return &JobHandler{
		Job: job,
	}
}

// Pipe readers, writer and closers for fanout the same writer.
func storageReadWriteCloser(count int, compress bool) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		if compress {
			gw := gzip.NewWriter(pw)
			pws = append(pws, gw)
			pcs = append(pcs, gw)
		} else {
			pws = append(pws, pw)
		}

		// This following append method must not be moved before pcs = append(pcs, gw) if compress is in use as the closer won't be able to close properly.
		// Thus, we put this line here and do not move it to other place.
		pcs = append(pcs, pw)
	}

	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
}

// Save database dump to different storages.
func (handler *JobHandler) save() error {
	job := handler.Job
	storages := handler.getStorages()

	numberOfStorages := len(storages)

	errCh := make(chan error, numberOfStorages+1)

	dumper, err := handler.getDumper()

	if err != nil {
		return fmt.Errorf("could not get dumper: %v", err)
	}

	if numberOfStorages > 0 {
		// Use pipe to pass content from the database dump to different writer.
		readers, writer, closer := storageReadWriteCloser(numberOfStorages, job.Gzip)

		var dumpWg sync.WaitGroup
		dumpWg.Add(1)
		go func() {
			err := dumper.Dump(writer)
			if err != nil {
				errCh <- err
			}

			// We must call .Done before the closer.Close method
			// writer and readers are connected via pipe and readers wait for the closer.Close to signal EOF so they can finish reading.
			// If we call .Done after close then it will block as dumpWg has not finished yet while readers wait for the EOF signal.
			dumpWg.Done()

			// We must call closer.Close() after the dump call. Then it will signal all readers with proper EOF.
			if closeErr := closer.Close(); closeErr != nil {
				slog.Error("can not close pipe readers and writers", slog.Any("error", closeErr))
			}
		}()

		var readWg sync.WaitGroup
		readWg.Add(numberOfStorages)
		for i, s := range storages {
			storage := s
			go func(i int) {
				defer readWg.Done()

				pathGenerator := func(filename string) string {
					return fileutil.EnsureFileName(filename, job.Gzip, job.Unique)
				}

				e := storage.Save(readers[i], pathGenerator)
				if e != nil {
					errCh <- e
				}
			}(i)
		}

		go func() {
			dumpWg.Wait()
			readWg.Wait()
			close(errCh)
		}()

		var allErrors []error

		for err := range errCh {
			allErrors = append(allErrors, err)
		}

		if len(allErrors) > 0 {
			return errors.Join(allErrors...)
		}
	}

	return nil
}

// Get all storage structs based on job configuration.
func (handler *JobHandler) getStorages() []storage.Storage {
	var storages []storage.Storage

	v := reflect.ValueOf(handler.Job.Storage)
	for i := 0; i < v.NumField(); i++ {
		field := v.Field(i)
		switch field.Kind() {
		case reflect.Slice:
			for i := 0; i < field.Len(); i++ {
				s, ok := field.Index(i).Interface().(storage.Storage)
				if ok {
					storages = append(storages, s)
				}
			}
		}
	}

	return storages
}

// Get the database dumper.
func (handler *JobHandler) getDumper() (dumper.Dumper, error) {
	job := handler.Job

	switch job.DBDriver {
	case "mysql":
		return dumper.NewMysqlNativeDump(job)
	case "postgresql":
		return dumper.NewPgDump(job)
	case "mysqldump":
		return dumper.NewMysqlDump(job)
	case "pgdump":
		return dumper.NewPgDump(job)
	default:
		return nil, fmt.Errorf("%s is not a supported database driver", job.DBDriver)
	}
}

// Do the job.
func (handler *JobHandler) Do() *jobresult.JobResult {
	start := time.Now()
	result := &jobresult.JobResult{}

	defer func() {
		elapsed := time.Since(start)
		result.Elapsed = elapsed
	}()

	result.JobName = handler.Job.Name

	err := handler.save()
	if err != nil {
		result.Error = fmt.Errorf("failed to store dump file %v", err)
	}

	return result
}
package fileutil

import (
	"bytes"
	"fmt"
	"io"
	"log/slog"
	"math/rand"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// Ensure a file has unique name when necessary.
func ensureUniqueness(path string, unique bool) string {
	if !unique {
		return path
	}

	dir, filename := filepath.Split(path)

	now := time.Now().UTC().Format("20060102150405")
	filename = now + "-" + filename

	return filepath.Join(dir, filename)
}

// Ensure a file has proper file extension.
func EnsureFileSuffix(filename string, shouldGzip bool) string {
	if !shouldGzip {
		return filename
	}

	fileExt := filepath.Ext(filename)
	if fileExt == ".gz" {
		return filename
	}

	return filename + ".gz"
}

func EnsureFileName(path string, shouldGzip, unique bool) string {
	p := EnsureFileSuffix(path, shouldGzip)
	return ensureUniqueness(p, unique)
}

// Check if file content is gzipped
func IsGzipped(filename string) bool {
	file, err := os.Open(filename)

	if err != nil {
		return false
	}

	defer func() {
		err := file.Close()
		if err != nil {
			slog.Error("fail to close file", slog.Any("error", err), slog.String("filename", file.Name()))
		}
	}()

	buf := make([]byte, 2)

	_, err = io.ReadFull(file, buf)

	if err != nil {
		return false
	}

	return bytes.Equal(buf, []byte{0x1f, 0x8b})
}

// List all files under a directory, support passing a pattern
// It does not support reading nested files.
func ListFiles(dir, pattern, skipExt string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}

	var files []string

	for _, v := range entries {
		if v.IsDir() {
			continue
		}

		if pattern != "" {
			matched, err := filepath.Match(pattern, v.Name())
			if err != nil {
				return nil, fmt.Errorf("invalid pattern: %w", err)
			}

			if !matched {
				continue
			}
		}

		// skip the file that has the matching suffix if specified
		if strings.TrimSpace(skipExt) != "" && strings.HasSuffix(v.Name(), skipExt) {
			continue
		}

		files = append(files, filepath.Join(dir, v.Name()))
	}

	return files, nil
}

// Generate a random string of the specified length using alphabetic characters
func GenerateRandomName(n int) string {
	const letterBytes = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

	b := make([]byte, n)
	for i := range b {
		b[i] = letterBytes[rand.Intn(len(letterBytes))]
	}
	return string(b)
}

// Get the working directory, fall back to user home or the temp dir
func WorkDir() string {
	dir, err := os.Getwd()

	if err != nil {
		slog.Error("can not get the current directory, use $HOME instead", slog.Any("error", err))
		dir, err = os.UserHomeDir()
		if err != nil {
			slog.Error("can not get the user home directory, use /tmp instead", slog.Any("error", err))
			dir = os.TempDir()
		}
	}

	return dir
}
